define({"topics":[{"title":"DCPS","href":"t_ReplacingDCPSForDriverModuleLite.html","menu":{"hasChildren":true},"tocID":"tocId-d46e154945","next":"tocId-d46e154945"},{"title":"ICE","href":"t_ICE-Replacement_15983908.html","menu":{"hasChildren":true},"tocID":"tocId-d46e160563","next":"tocId-d46e160563"},{"title":"ICN","href":"t_ReplacingTheICN_Parent.html","menu":{"hasChildren":true},"tocID":"tocId-d46e162652","next":"tocId-d46e162652"},{"title":"KASC","href":"t_ReplacingTheKASCBoards_Parent.html","menu":{"hasChildren":true},"tocID":"tocId-d46e165571","next":"tocId-d46e165571"},{"title":"Leak Sensor","href":"t_ReplacingLeakSensors.html","menu":{"hasChildren":true},"tocID":"tocId-d46e174560","next":"tocId-d46e174560"},{"title":"PDU","href":"t_GOC-PDU-Replacement_15385443.html","menu":{"hasChildren":true},"tocID":"tocId-d46e175899","next":"tocId-d46e175899"},{"title":"Replacing the cabinet monitor","shortdesc":"<p class=\"shortdesc\">The cabinet monitor communicates system status information to the Scan Control Processor (SCP) in the Integrated Control Engine (ICE) through Ethernet interface. The cabinet monitor also distributes 1-wire signals. <\/p>","href":"t_ReplacingTheCabinetMonitor.html","attributes":{"data-id":"id_2001579"},"menu":{"hasChildren":true},"tocID":"id_2001579-d46e185206","next":"id_2001579-d46e185206"},{"title":"Replacing the driver module lite","shortdesc":"<p class=\"shortdesc\">Provides information about the task of replacing the driver module lite in the Integrated System Cabinet (ISC).<\/p>","href":"t_ReplacingTheDriverModuleLite_Parent.html","attributes":{"data-id":"id_2007415"},"menu":{"hasChildren":true},"tocID":"id_2007415-d46e186143","next":"id_2007415-d46e186143"},{"title":"Replacing the Dynamic Disable (DD) filter","shortdesc":"<p class=\"shortdesc\">Replace the DD filter on the Integrated System Cabinet (ISC) Penetration Wall (PW).<\/p>","href":"t_ReplacingTheDynamicDisableDDFilter_Parent.html","attributes":{"data-id":"id_2007410"},"menu":{"hasChildren":true},"tocID":"id_2007410-d46e187186","next":"id_2007410-d46e187186"},{"title":"Replacing the exciter","shortdesc":"<p class=\"shortdesc\">Removal and installation instructions for replacing the exciter.<\/p>","href":"t_Replacing_the_exciter_first_topic.html","attributes":{"data-id":"id_2021984"},"menu":{"hasChildren":true},"tocID":"id_2021984-d46e188123","next":"id_2021984-d46e188123"},{"title":"Replacing the gradient power supply","shortdesc":"<p class=\"shortdesc\">Replaces any of the threes gradient power supplies, x-axis, y-axis, or z-axis.<\/p>","href":"t_ReplacingTheGradientPowerSupplyRPS.html","attributes":{"data-id":"id_2003844"},"menu":{"hasChildren":true},"tocID":"id_2003844-d46e192364","next":"id_2003844-d46e192364"},{"title":"Replacing the Gradient Amplifier (RGA)","shortdesc":"<p class=\"shortdesc\">Follow this procedure to replace the gradient amplifier (RGA). The RGA unit weighs enough (about 90.7 kg [200 lbs]) that a hoist kit is required.<span class=\"ph\"> There are currently two types of gradient amplifiers. One has RADLOK connections, the other has lug connections.<\/span><\/p>","href":"t_ReplacingTheGradientAmpRGA.html","attributes":{"data-id":"id_2003845"},"menu":{"hasChildren":true},"tocID":"id_2003845-d46e194026","next":"id_2003845-d46e194026"},{"title":"Replacing the High Order Shim (HOS) filter","shortdesc":"<p class=\"shortdesc\">Remove the High Order Shim (HOS) filter from the Integrated System Cabinet Penetration Wall (ISC PW) and install a replacement filter.<\/p>","href":"t_ReplacingTheHighOrderShimHOSFilter.html","attributes":{"data-id":"id_2016635"},"menu":{"hasChildren":true},"tocID":"id_2016635-d46e198944","next":"id_2016635-d46e198944"},{"title":"Replacing the High Order Shim (HOS) power supply","shortdesc":"<p class=\"shortdesc\">Removes either the NavShim (<span class=\"ph\">5778344<\/span>) or ProDrive (<span class=\"ph\">5847514<\/span>) High Order Shim (HOS) power supply from the Integrated System Cabinet (ISC) and installs a replacement NavShim or ProDrive HOS power supply.<\/p>","href":"t_ReplacingTheHighOrderShimHOSPowerSupply_ISCCabinet.html","attributes":{"data-id":"id_2016548"},"menu":{"hasChildren":true},"tocID":"id_2016548-d46e199985","next":"id_2016548-d46e199985"},{"title":"Replacing the Integrated System Cabinet (ISC) Ethernet switch","href":"t_ReplacingtheEthernetSwitchISC.html","attributes":{"data-id":"id_2001558"},"menu":{"hasChildren":true},"tocID":"id_2001558-d46e201033","next":"id_2001558-d46e201033"},{"title":"<span class=\"ph\">Replacing the ISC top fan assembly<\/span>","shortdesc":"<p class=\"shortdesc\">Remove and replace the Integrated System Cabinet (ISC) top fan assembly.<\/p>","href":"t_ReplacingTheTopFanAssembly_Parent.html","attributes":{"data-id":"id_2011427"},"menu":{"hasChildren":true},"tocID":"id_2011427-d46e202386","next":"id_2011427-d46e202386"},{"title":"Replacing the <span class=\"ph\">Patient Handling Power Supply (PHPS) 2<\/span>","shortdesc":"<p class=\"shortdesc\">This procedure describes the removal and installation of the <span class=\"ph\">Patient Handling Power Supply 2 (PHPS2)<\/span>, which is a core component of the Patient Handling Sub-System (PHSS). The <span class=\"ph\">PHPS2<\/span> provides power to the other components in the PHSS, and serves as an interface between them and the equipment room.<\/p>","href":"t_ReplacingthePHPS2.html","attributes":{"data-id":"id_2001608"},"menu":{"hasChildren":true},"tocID":"id_2001608-d46e203220","next":"id_2001608-d46e203220"},{"title":"Replacing the PS filter box","shortdesc":"<p class=\"shortdesc\">Replace the PS filter box in the Integrated System Cabinet (ISC) Penetration Wall (PW).<\/p>","href":"t_ReplacingthePSFilterBox.html","attributes":{"data-id":"id_2001611"},"menu":{"hasChildren":true},"tocID":"id_2001611-d46e204490","next":"id_2001611-d46e204490"},{"title":"Replacing the RF amplifier","shortdesc":"<p class=\"shortdesc\">This procedure contains information on replacing the dual drive RF amp, which is located in the ISC cabinet. The dual drive RF amp unit weighs enough [about 335 lbs {152kg}] that a hoist kit is required.<\/p>","href":"t_RFAmplifierReplacement.html","attributes":{"data-id":"id_2003870"},"menu":{"hasChildren":true},"tocID":"id_2003870-d46e205427","next":"id_2003870-d46e205427"}]});